import { randomBytes } from "node:crypto";
import { existsSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

type Status = "open" | "done";

type Task = {
  id: number;
  title: string;
  status: Status;
  createdAt: string;
  tags: string[];
  due?: string;
  completedAt?: string;
};

type Database = { tasks: Task[]; nextId: number };

const file = process.env.TASKBOARD_FILE || join(process.cwd(), ".taskboard.json");

function fail(message: string): never {
  throw new Error(message);
}

function isDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

function today(): string {
  const now = new Date();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${now.getFullYear()}-${month}-${day}`;
}

function load(): Database {
  if (!existsSync(file)) return { tasks: [], nextId: 1 };
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(file, "utf8"));
  } catch {
    fail("malformed database");
  }
  if (!parsed || typeof parsed !== "object" || !Array.isArray((parsed as any).tasks)) fail("malformed database");
  const raw = parsed as any;
  const tasks = raw.tasks as unknown[];
  if (raw.nextId !== undefined && (!Number.isInteger(raw.nextId) || raw.nextId < 1)) fail("malformed database");
  let maxId = 0;
  for (const item of tasks) {
    if (!item || typeof item !== "object") fail("malformed database");
    const task = item as any;
    if (!Number.isInteger(task.id) || task.id < 1 || typeof task.title !== "string" || !["open", "done"].includes(task.status) ||
      typeof task.createdAt !== "string" || !Array.isArray(task.tags) || task.tags.some((tag: unknown) => typeof tag !== "string") ||
      (task.due !== undefined && (typeof task.due !== "string" || !isDate(task.due))) ||
      (task.completedAt !== undefined && typeof task.completedAt !== "string")) fail("malformed database");
    if (task.id > maxId) maxId = task.id;
  }
  const ids = tasks.map((task: any) => task.id);
  if (new Set(ids).size !== ids.length) fail("malformed database");
  const nextId = raw.nextId === undefined ? maxId + 1 : raw.nextId;
  if (nextId <= maxId) fail("malformed database");
  return { tasks: tasks as Task[], nextId };
}

function save(database: Database): void {
  const temporary = `${file}.tmp-${process.pid}-${randomBytes(8).toString("hex")}`;
